<?php
$preview=$_SESSION['results_preview']??null;
if($preview && $preview['expires']>=time()):
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$changes=$preview['changes']??[];
?>
<div class="container my-4 card p-3"><h4>Validated draft preview</h4>
<p><?= (int)$preview['count'] ?> records validated. <?= ($preview['mode']??'MERGE')==='REPLACE'?'Complete-file replacement':'Incremental import' ?>: <?= (int)($changes['added']??0) ?> added, <?= (int)($changes['changed']??0) ?> changed, <?= (int)($changes['removed']??0) ?> removed, <?= (int)($changes['unchanged']??0) ?> unchanged. Showing up to 20 records in each table. Importing saves an unpublished draft.</p>
<div class="table-responsive"><table class="table"><tr><th>Admission number</th><th>Subject</th><th>Internal</th><th>External</th><th>Total</th><th>Grade</th><th>Credits</th><th>Status</th></tr><?php foreach($preview['rows'] as $r):?><tr><?php foreach(['htno','subject_code','internal_marks','external_marks','total_marks','grade_letter','credits_registered','result_status'] as $key):?><td><?= $e($r[$key]) ?></td><?php endforeach;?></tr><?php endforeach;?></table></div>
<?php if(!empty($preview['changed_sample'])): ?><h5>Records changing</h5><table class="table"><tr><th>Admission number / Subject</th><th>Changes</th></tr><?php foreach($preview['changed_sample'] as $change): ?><tr><td><?= $e($change['after']['htno'].' / '.$change['after']['subject_code']) ?></td><td><?php foreach(['internal_marks'=>'Internal','external_marks'=>'External','total_marks'=>'Total','grade_letter'=>'Grade','grade_points'=>'Grade points','credits_registered'=>'Credits','result_status'=>'Status'] as $key=>$label): if($change['before'][$key]===$change['after'][$key]){continue;} ?><div><?= $e($label.': '.($change['before'][$key]??'blank').' → '.($change['after'][$key]??'blank')) ?></div><?php endforeach; ?></td></tr><?php endforeach; ?></table><?php endif; ?>
<?php if(!empty($preview['removed_sample'])): ?><h5>Records being removed</h5><table class="table"><tr><th>Admission number</th><th>Subject</th><th>Grade</th></tr><?php foreach($preview['removed_sample'] as $r): ?><tr><td><?= $e($r['htno']) ?></td><td><?= $e($r['subject_code']) ?></td><td><?= $e($r['grade_letter']) ?></td></tr><?php endforeach; ?></table><?php endif; ?>
<form method="post"><input type="hidden" name="action" value="commit_results_preview"><input type="hidden" name="secretcode" value="<?= $e($_SESSION['secretcode']) ?>"><input type="hidden" name="preview_token" value="<?= $e($preview['token']) ?>">
<label class="form-label">Reason / authority for this import</label><textarea name="correction_reason" class="form-control mb-3" <?= !empty($changes['changed'])||!empty($changes['removed'])||($preview['mode']??'')==='REPLACE'?'required':'' ?>></textarea><button class="btn btn-primary">Import validated draft</button></form></div>
<?php endif; ?>
